static int64_t gs_verify_f64(const uint8_t *p, int64_t n, uint8_t *bm) {
    const uint8_t *e = p + n;
    int64_t q = 0, cnt = 0;
    (void)e; (void)bm;
    while (q < n) {
    if (n - q < 8) return -1;
    q += 8;
        cnt++;
    }
    if (q != n) return -1;
    return cnt;
}

static int64_t gs_verify_i64(const uint8_t *p, int64_t n, uint8_t *bm) {
    const uint8_t *e = p + n;
    int64_t q = 0, cnt = 0;
    (void)e; (void)bm;
    while (q < n) {
    if (n - q < 8) return -1;
    q += 8;
        cnt++;
    }
    if (q != n) return -1;
    return cnt;
}

